// @pit: {"label": "Write nested-run module, tests, wire index.ts and push.ts"}
async ({ workspace: { read, edit } }) => {
  const mod = `// A pi-action run inside a pi-action run (the agent's tools ran src/index.ts) works on the same thread refs as the run
// around it, and breaks that run: its storage finds its local ref moved. So a run marks its own environment, which
// every tool and child process inherits, and a run that finds the mark stops before it does anything.

/** Set to the process ID of the run while pi-action runs. */
export const RUNNING_ENV = "PI_ACTION_RUNNING";

type Env = Record<string, string | undefined>;

/** Why this process must not run: it runs inside a pi-action run. Undefined outside one. */
export function nestedRun(env: Readonly<Env>): string | undefined {
	const outer = env[RUNNING_ENV];
	if (outer === undefined || outer === "") {
		return undefined;
	}
	return \`pi-action is already running in this job (\${RUNNING_ENV}=\${outer}). A run started from the agent's tools would change the thread of the run around it, so this one does nothing\`;
}

/** Marks \`env\` (the process environment) as inside this run; when it already is, returns why the run must stop. */
export function claimRun(env: Env, pid: number = process.pid): string | undefined {
	const nested = nestedRun(env);
	if (nested === undefined) {
		env[RUNNING_ENV] = String(pid);
	}
	return nested;
}
`;
  const test = `import { execFileSync, spawnSync } from "node:child_process";

import { describe, expect, it } from "vitest";

import { claimRun, nestedRun, RUNNING_ENV } from "./nested-run.ts";

describe("claimRun", () => {
	it("marks the environment of a run, which its tools inherit", () => {
		const env: Record<string, string | undefined> = {};
		expect(claimRun(env, 123)).toBeUndefined();
		expect(env[RUNNING_ENV]).toBe("123");
		expect(nestedRun(env)).toContain(\`\${RUNNING_ENV}=123\`);
	});

	it("refuses a run inside a run, and keeps the outer run's mark", () => {
		const env: Record<string, string | undefined> = { [RUNNING_ENV]: "7" };
		expect(claimRun(env, 123)).toBe(
			"pi-action is already running in this job (PI_ACTION_RUNNING=7). A run started from the agent's tools would change the thread of the run around it, so this one does nothing",
		);
		expect(env[RUNNING_ENV]).toBe("7");
	});

	it("ignores an empty mark", () => {
		expect(nestedRun({ [RUNNING_ENV]: "" })).toBeUndefined();
	});
});

// Only PATH and the mark: if the guard failed, the child would find no event, token, or inputs to act on.
const nestedEnv = { PATH: process.env["PATH"], [RUNNING_ENV]: "42" };
const node = (script: string) =>
	spawnSync(
		process.execPath,
		["--disable-warning=ExperimentalWarning", script],
		{ encoding: "utf8", env: nestedEnv, timeout: 20_000 },
	);

describe("the entry points inside a run", () => {
	it("src/index.ts fails at once and does nothing", () => {
		const result = node("src/index.ts");
		expect(result.status).toBe(1);
		expect(result.stdout).toContain(
			"::error::pi-action is already running in this job (PI_ACTION_RUNNING=42)",
		);
		expect(result.stdout).not.toContain("::group::");
	});

	it("src/push.ts pushes nothing", () => {
		const result = node("src/push.ts");
		expect(result.status).toBe(0);
		expect(result.stdout).toContain(
			"::warning::Not saving the thread: pi-action is already running in this job (PI_ACTION_RUNNING=42)",
		);
	});

	it("leaves a run outside one alone", () => {
		const output = execFileSync(
			process.execPath,
			[
				"--disable-warning=ExperimentalWarning",
				"--input-type=module",
				"-e",
				'const { claimRun } = await import("./src/nested-run.ts"); console.log(String(claimRun(process.env)));',
			],
			{ encoding: "utf8", env: { PATH: process.env["PATH"] } },
		);
		expect(output.trim()).toBe("undefined");
	});
});
`;
  await edit("src/nested-run.ts", { revision: null, changes: [{ kind: "replaceFile", content: mod }] });
  await edit("src/nested-run.test.ts", { revision: null, changes: [{ kind: "replaceFile", content: test }] });
  const idx = await read("src/index.ts", { format: "raw" });
  let c = idx.content;
  const imp = `import { readActionInputs } from "./inputs.ts";\n`;
  c = c.replace(imp, imp + `import { claimRun } from "./nested-run.ts";\n`);
  const start = c.indexOf("// An invalid input");
  if (start < 0) throw new Error("no start");
  const body = c.slice(start);
  // indent body one more tab and wrap
  const indented = body.trimEnd().split("\n").map((l) => (l === "" ? l : "\t" + l)).join("\n");
  c = c.slice(0, start) + `// First, before it reads inputs or touches a ref: a run that the agent's tools started inside this one stops.\nconst nested = claimRun(process.env);\nif (nested === undefined) {\n${indented}\n} else {\n\tsetFailed(nested);\n}\n`;
  await edit("src/index.ts", { revision: idx.revision, changes: [{ kind: "replaceFile", content: c }] });
  const p = await read("src/push.ts", { format: "raw" });
  let d = p.content;
  d = d.replace(`import { parsePositiveInteger } from "./inputs.ts";\n`, `import { parsePositiveInteger } from "./inputs.ts";\nimport { nestedRun } from "./nested-run.ts";\n`);
  const a = `if (process.argv[1]?.endsWith("push.ts") === true) {\n\tpushThread(`;
  if (!d.includes(a)) throw new Error("push missing");
  d = d.replace(a, `const nested = nestedRun(process.env);\nif (process.argv[1]?.endsWith("push.ts") === true && nested !== undefined) {\n\t// The run around this one saves its own thread.\n\twarning(\`Not saving the thread: \${nested}\`);\n} else if (process.argv[1]?.endsWith("push.ts") === true) {\n\tpushThread(`);
  await edit("src/push.ts", { revision: p.revision, changes: [{ kind: "replaceFile", content: d }] });
  return "ok";
}
